"""Synthetic run.json pool for tests/test_paper_render.py.

``write_pool(root)`` writes one schema-v2 record per job of every table
target in experiments/paper/targets.yaml under ``root/runs`` (numbers are
deterministic per job key). The pool is generated by the tests,
not committed. After an intended layout change, re-render expected/:

    python tests/fixtures/paper/generate_pool.py
"""
from __future__ import annotations

import hashlib
import json
import random
import shutil
import sys
import tempfile
from pathlib import Path

HERE = Path(__file__).resolve().parent
sys.path.insert(0, str(HERE.parents[2]))

from experiments.paper.targets import load_registry  # noqa: E402
from scion.util.provenance import config_sha256  # noqa: E402

MiB = 2 ** 20
GiB = 2 ** 30
GIT_SHA = "0123456789abcdef0123456789abcdef01234567"
BASE = {"mipnerf360": (22.0, 0.60, 0.43), "tandt": (18.6, 0.63, 0.42),
        "deepblending": (24.0, 0.81, 0.44), "synthetic": (24.4, 0.90, 0.10),
        "campus": (16.8, 0.43, 0.56)}
GROUPS = (("id", -0.5, 13), ("sideways", 0.2, 20), ("opposite", 1.6, 61))  # campus: (group, PSNR drop, views)


def _sha(text: str) -> str:
    return hashlib.sha256(text.encode()).hexdigest()


def record(job) -> dict:
    k = job.key
    rng = random.Random(repr(k))
    large = k.variant == "ours_large"
    psnr, ssim, lpips = BASE[k.dataset]
    psnr += (1.0 if large else 0.0) + rng.uniform(-0.3, 0.3)
    ssim += (0.04 if large else 0.0) + rng.uniform(-0.01, 0.01)
    lpips += (-0.08 if large else 0.0) + rng.uniform(-0.02, 0.02)
    q_bytes = int((2.6 if large else 1.0) * 1.25 * MiB * rng.uniform(0.85, 1.15))
    if k.dataset == "synthetic":
        q_bytes //= 7
    n = int(1.7e6 * (1.1 if large else 1.0) * rng.uniform(0.9, 1.1))
    metrics = {}
    for level, dq, size in (("raw", 0.02, int(q_bytes * 1.75)), ("quantized", 0.0, q_bytes),
                            ("codec", -0.05, int(q_bytes * 0.4))):
        metrics[level] = {"psnr": round(psnr + dq, 4), "ssim": round(ssim + dq / 10, 4),
                          "lpips": round(lpips - dq / 10, 4), "size_bytes": size,
                          "bpg": round(size * 8 / n, 4), "fps": round(rng.uniform(0.9, 1.1), 3),
                          "n_gaussians": n}
        if k.dataset == "campus":
            metrics[level]["by_subset"] = {
                g: {"psnr": round(psnr + dq - drop, 4), "ssim": round(ssim + dq / 10 - drop / 20, 4),
                    "lpips": round(lpips - dq / 10 + drop / 30, 4), "n_views": nv}
                for g, drop, nv in GROUPS}
    bench = k.tag is not None
    tier = k.tag or "cuda"
    K = 512 if large else 128
    insts = int(55000 * rng.uniform(0.95, 1.05))
    rec = {
        "schema_version": 2, "status": "DONE", "error": None,
        "job": {"variant": k.variant, "ablation": k.ablation, "dataset": k.dataset,
                "scene": k.scene, "seed": k.seed, "tag": k.tag},
        "slot": k.slot, "overrides": list(job.overrides),
        "config_sha256": config_sha256(list(job.overrides)), "git_sha": GIT_SHA,
        "gpu": "NVIDIA GeForce RTX 5090" if bench else "Tesla V100-SXM2-32GB",
        "backend_tiers": {"assemble_fused": tier, "assemble_fused_bwd": tier},
        "versions": {"python": "3.9.25", "torch": "2.8.0+cu128", "cuda": "12.8",
                     "gsplat": "1.5.3", "scion": "0.2.0a0", "constriction": "0.4.1",
                     "scikit_learn": "1.6.1"},
        "started_at": "2026-10-20T12:00:00Z", "ended_at": "2026-10-20T14:00:00Z",
        "train_time_s": round((3600 if tier == "python" else 2400) * rng.uniform(0.95, 1.05)
                              if bench else rng.uniform(5300, 7900), 1),
        "median_step_s": round((0.12 if tier == "python" else 0.08) * rng.uniform(0.95, 1.05), 4),
        "peak_vram_bytes": int(rng.uniform(9, 15.4) * GiB),
        "split": {"eval_mode": "interval", "eval_interval": 8, "train_split_fraction": None,
                  "downscale_factor": 4, "n_train": 161, "n_eval": 24,
                  "eval_images_sha256": _sha(f"{k.dataset}/{k.scene}"),
                  "data_sha256": _sha(f"data/{k.scene}")},
        "n_gaussians": n,
        "model_stats": {"num_candidates": K, "active_candidates": K, "num_instances": insts,
                        "num_splats": int(K * rng.uniform(28, 34)),
                        "mean_splats_per_candidate": round(rng.uniform(28, 34), 2),
                        "effective_candidates": round(K * rng.uniform(0.85, 0.95), 2),
                        "instances_per_candidate": round(insts / K, 2)},
        "compression_level": "codec", "metrics": metrics,
        "codec": {"options": {"M": 3, "B": 256, "min_rows_for_svq": 64, "pos_bits": 16, "seed": 0,
                              "lzma_wrap": True, "position_format": "tmc13", "tmc13_quant_step": 0.001,
                              "svq_instance_attrs": True, "instance_svq_M": 4, "instance_svq_B": 256},
                  "position_format_used": "tmc13", "tmc13_version": "release-v23.0-rc2 a3d15c5"},
        "artifacts": {"checkpoints": {"raw": "checkpoints/raw.ckpt",
                                      "quantized": "checkpoints/quantized.ckpt", "codec": "codec.omg"},
                      "eval_views": {lv: f"eval_views/{lv}" for lv in metrics},
                      "templates": "candidates", "train_log": "train.log"},
    }
    return rec


def write_pool(root: Path) -> None:
    reg = load_registry()
    tables = [n for n, t in reg.targets.items() if t.renderer]
    for job in reg.jobs(tables):
        path = job.key.path(root / "runs")
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(json.dumps(record(job), indent=1) + "\n")


def main() -> int:
    from experiments.paper import render
    with tempfile.TemporaryDirectory() as tmp:
        write_pool(Path(tmp))
        if render.main(["all", "--runs-root", f"{tmp}/runs",
                        "--out", f"{tmp}/out"]):
            return 1
        shutil.rmtree(HERE / "expected", ignore_errors=True)
        shutil.copytree(Path(tmp) / "out" / "tables", HERE / "expected")
    return 0


if __name__ == "__main__":
    sys.exit(main())
